import java.util.*;

public class Main {
    int numRescueBoats(int[] people, int limit) {
        Arrays.sort(people);
        int n = people.length;
        boolean[] used = new boolean[n];
        int boats = 0;
        for (int i = 0; i < n; i++) {
            if (used[i]) continue;
            used[i] = true;
            boats++;
            for (int j = n - 1; j > i; j--) {                            // scans every other unpaired person
                if (!used[j] && people[i] + people[j] <= limit) {
                    used[j] = true;
                    break;
                }
            }
        }
        return boats;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.numRescueBoats(new int[]{3, 2, 2, 1}, 3));
    }
}

