def num_rescue_boats(people, limit):
    people.sort()
    left, right = 0, len(people) - 1
    boats = 0
    while left <= right:
        if people[left] + people[right] <= limit:
            left += 1                                             # the lightest person is paired with the heaviest
        right -= 1                                                    # the heaviest person always leaves on this boat
        boats += 1
    return boats


